public class FlashAACInputStream extends InputStream {
    private int _aacProfile;
    private int _channelConfig;
    private int _sampleRateIndex;
    private DataInputStream dis;
    private int countInBackBuffer = 0;
    private int backBufferLen = 65536;
    private byte[] backBuffer = new byte[this.backBufferLen];
    private int readBufferLen = 65536;
    private byte[] readBuffer = new byte[this.readBufferLen];

    public FlashAACInputStream(InputStream istream) throws IOException {
        this.dis = null;
        this.dis = new DataInputStream(istream);
        if (((char) this.dis.readByte()) != 'F' || ((char) this.dis.readByte()) != 'L' || ((char) this.dis.readByte()) != 'V') {
            throw new IOException("The file is not a FLV file.");
        }
        this.dis.readByte();
        byte exists = this.dis.readByte();
        if (exists != 5 && exists != 4) {
            throw new IOException("No Audio Stream");
        }
        this.dis.readInt();
    }

    @Override // java.io.InputStream
    public int read() throws IOException {
        byte[] b = new byte[1];
        read(b, 0, 1);
        return b[0] & 255;
    }

    @Override // java.io.InputStream
    public int read(byte[] b, int off, int len) throws IOException {
        int readBytes;
        if (off < 0 || len < 0 || b.length - off < len) {
            throw new IndexOutOfBoundsException();
        }
        if (len > this.readBufferLen) {
            throw new IndexOutOfBoundsException("len exceeds readBufferLen");
        }
        Log.d("FlashAACInputStream", "read: countInBackBuffer = " + this.countInBackBuffer);
        if (this.countInBackBuffer > 0) {
            if (this.countInBackBuffer >= len) {
                System.arraycopy(this.backBuffer, 0, b, off, len);
                if (this.countInBackBuffer > len) {
                    System.arraycopy(this.backBuffer, len, this.backBuffer, 0, this.countInBackBuffer - len);
                }
                this.countInBackBuffer -= len;
                return len;
            }
            System.arraycopy(this.backBuffer, 0, b, off, this.countInBackBuffer);
        }
        int remaining = len - this.countInBackBuffer;
        int b_off = off + this.countInBackBuffer;
        this.countInBackBuffer = 0;
        while (true) {
            readBytes = readFrame(this.readBuffer);
            remaining -= readBytes;
            if (remaining <= 0) {
                break;
            }
            if (remaining > 0) {
                System.arraycopy(this.readBuffer, 0, b, b_off, readBytes);
                b_off += readBytes;
            }
        }
        System.arraycopy(this.readBuffer, 0, b, b_off, readBytes + remaining);
        if (remaining < 0) {
            System.arraycopy(this.readBuffer, readBytes + remaining, this.backBuffer, 0, Math.abs(remaining));
            this.countInBackBuffer = Math.abs(remaining);
        }
        return len;
    }

    private int readFrame(byte[] buf) throws IOException {
        this.dis.readInt();
        byte tagType = this.dis.readByte();
        while (tagType != 8) {
            long skip = readNext3Bytes() + 11;
            this.dis.skipBytes((int) skip);
            tagType = this.dis.readByte();
        }
        long dataSize = readNext3Bytes() - 1;
        int timestamps = this.dis.readInt();
        long streamID = readNext3Bytes();
        byte audioHeader = this.dis.readByte();
        Log.d("FlashAACInputStream", "dataSize = " + dataSize + ", timestamps = " + timestamps + ", streamId = " + streamID + ", audioHeader = " + ((int) audioHeader));
        return fillBuffer(buf, (int) dataSize);
    }

    private boolean readAACHeader() throws IOException {
        byte head = this.dis.readByte();
        if (head != 0) {
            return false;
        }
        int bits = (((this.dis.readByte() & 255) * 256) + (this.dis.readByte() & 255)) << 16;
        this._aacProfile = readBits(bits, 5) - 1;
        int bits2 = bits << 5;
        this._sampleRateIndex = readBits(bits2, 4);
        this._channelConfig = readBits(bits2 << 4, 4);
        Log.d("FlashAACInputStream", "aacProf = " + this._aacProfile);
        Log.d("FlashAACInputStream", "_sampleRateIndex = " + this._sampleRateIndex);
        Log.d("FlashAACInputStream", "_channelConfig = " + this._channelConfig);
        if (this._aacProfile < 0 || this._aacProfile > 3) {
            throw new IOException("Unsupported AAC profile.");
        }
        if (this._sampleRateIndex > 12) {
            throw new IOException("Invalid AAC sample rate index.");
        }
        if (this._channelConfig > 6) {
            throw new IOException("Invalid AAC channel configuration.");
        }
        return true;
    }

    private int fillBuffer(byte[] buf, int dataSize) throws IOException {
        if (readAACHeader()) {
            return 0;
        }
        int dataSize2 = dataSize - 1;
        long bits = writeBits(writeBits(writeBits(0L, 12, 4095), 3, 0), 1, 1);
        buf[0] = (byte) (bits >> 8);
        buf[1] = (byte) bits;
        long bits2 = writeBits(writeBits(writeBits(writeBits(writeBits(writeBits(0L, 2, this._aacProfile), 4, this._sampleRateIndex), 1, 0), 3, this._channelConfig), 4, 0), 2, (dataSize2 + 7) & 6144);
        buf[2] = (byte) (bits2 >> 8);
        buf[3] = (byte) bits2;
        long bits3 = writeBits(writeBits(writeBits(0L, 11, (dataSize2 + 7) & 2047), 11, 2047), 2, 0);
        buf[4] = (byte) (bits3 >> 16);
        buf[5] = (byte) (bits3 >> 8);
        buf[6] = (byte) bits3;
        this.dis.readFully(buf, 7, dataSize2);
        buf[dataSize2 + 7] = 0;
        return dataSize2 + 8;
    }

    private int readBits(int x, int length) {
        int r = x >> (32 - length);
        return r;
    }

    public long writeBits(long x, int length, int value) {
        long mask = 4294967295 >> (32 - length);
        return (x << length) | (value & mask);
    }

    private long readNext3Bytes() throws IOException {
        return (this.dis.readUnsignedByte() * 256 * 256) + (this.dis.readUnsignedByte() * 256) + this.dis.readUnsignedByte();
    }

