    public void beep(final long count) {
        this.cordova.getThreadPool().execute(new Runnable() { // from class: org.apache.cordova.dialogs.Notification.1
            @Override // java.lang.Runnable
            public void run() {
                Uri ringtone = RingtoneManager.getDefaultUri(2);
                Ringtone notification = RingtoneManager.getRingtone(Notification.this.cordova.getActivity().getBaseContext(), ringtone);
                if (notification != null) {
                    for (long i = 0; i < count; i++) {
                        notification.play();
                        long timeout = 5000;
                        while (notification.isPlaying() && timeout > 0) {
                            timeout -= 100;
                            try {
                                Thread.sleep(100L);
                            } catch (InterruptedException e) {
                                Thread.currentThread().interrupt();
                            }
                        }
                    }
                }
            }
        });
    }

