    private boolean prepareOnly = true;
    private int seekOnPrepared = 0;

    public enum MODE {
        NONE,
        PLAY,
        RECORD
    }

    public enum STATE {
        MEDIA_NONE,
        MEDIA_STARTING,
        MEDIA_RUNNING,
        MEDIA_PAUSED,
        MEDIA_STOPPED,
        MEDIA_LOADING
    }

    public AudioPlayer(AudioHandler handler, String id, String file) {
        this.audioFile = null;
        this.recorder = null;
        this.tempFile = null;
        this.handler = handler;
        this.id = id;
        this.audioFile = file;
        this.recorder = new MediaRecorder();
        if (Environment.getExternalStorageState().equals("mounted")) {
            this.tempFile = Environment.getExternalStorageDirectory().getAbsolutePath() + "/tmprecording.3gp";
        } else {
            this.tempFile = "/data/data/" + handler.cordova.getActivity().getPackageName() + "/cache/tmprecording.3gp";
        }
    }

    public void destroy() {
        if (this.player != null) {
            if (this.state == STATE.MEDIA_RUNNING || this.state == STATE.MEDIA_PAUSED) {
                this.player.stop();
                setState(STATE.MEDIA_STOPPED);
            }
            this.player.release();
            this.player = null;
        }
        if (this.recorder != null) {
            stopRecording();
            this.recorder.release();
            this.recorder = null;
        }
    }

    public void startRecording(String file) {
        switch (this.mode) {
            case PLAY:
                Log.d(LOG_TAG, "AudioPlayer Error: Can't record in play mode.");
                sendErrorStatus(MEDIA_ERR_ABORTED);
                break;
            case NONE:
                this.audioFile = file;
                this.recorder.setAudioSource(1);
                this.recorder.setOutputFormat(0);
                this.recorder.setAudioEncoder(0);
                this.recorder.setOutputFile(this.tempFile);
                try {
                    this.recorder.prepare();
                    this.recorder.start();
                    setState(STATE.MEDIA_RUNNING);
                    break;
                } catch (IOException e) {
                    e.printStackTrace();
                    sendErrorStatus(MEDIA_ERR_ABORTED);
                    return;
                } catch (IllegalStateException e2) {
                    e2.printStackTrace();
                    sendErrorStatus(MEDIA_ERR_ABORTED);
                    return;
                }
            case RECORD:
                Log.d(LOG_TAG, "AudioPlayer Error: Already recording.");
                sendErrorStatus(MEDIA_ERR_ABORTED);
                break;
        }
    }

    public void moveFile(String file) {
        File f = new File(this.tempFile);
        if (!file.startsWith("/")) {
            if (Environment.getExternalStorageState().equals("mounted")) {
                file = Environment.getExternalStorageDirectory().getAbsolutePath() + File.separator + file;
            } else {
                file = "/data/data/" + this.handler.cordova.getActivity().getPackageName() + "/cache/" + file;
            }
        }
        String logMsg = "renaming " + this.tempFile + " to " + file;
        Log.d(LOG_TAG, logMsg);
        if (!f.renameTo(new File(file))) {
            Log.e(LOG_TAG, "FAILED " + logMsg);
        }
    }

    public void stopRecording() {
        if (this.recorder != null) {
            try {
                if (this.state == STATE.MEDIA_RUNNING) {
                    this.recorder.stop();
                    setState(STATE.MEDIA_STOPPED);
                }
                this.recorder.reset();
                moveFile(this.audioFile);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    public void startPlaying(String file) {
        if (readyPlayer(file) && this.player != null) {
            this.player.start();
            setState(STATE.MEDIA_RUNNING);
            this.seekOnPrepared = 0;
            return;
        }
        this.prepareOnly = false;
    }

    public void seekToPlaying(int milliseconds) {
